        const mainWindow = this.getMainWindow();
        if (mainWindow && !mainWindow.isDestroyed()) {
          mainWindow.webContents.send('global-shortcut', { action: 'selectiveScreenshot' });
        }
      } else if (actionId === 'general:capture-and-process') {
